src/StakingManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IRewardAdapter.sol";
import "./interfaces/IPositionAdapter.sol";
import "./FeeTransferHelper.sol";
import "./ReferralTracker.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Minimal vault interface for StakingManager
interface ISnuggleVaultMinimal {
    function positions(uint256 tokenId) external view returns (
        uint256 tokenId_,
        bytes32 poolId,
        address owner,
        uint24 rangeWidthBps,
        int24 currentTickLower,
        int24 currentTickUpper,
        bool autoSnuggleEnabled,
        bool autoCompoundEnabled,
        uint64 rebalanceDelay,
        uint64 outOfRangeSince,
        uint32 totalRebalances,
        uint32 lastRebalanceTime,
        uint64 depositTimestamp,
        uint128 cumulativeFees0,
        uint128 cumulativeFees1,
        uint128 cumulativeRewards,
        uint128 __reserved
    );
    function approvedPools(bytes32 poolId) external view returns (
        address pool,
        address token0,
        address token1,
        uint24 fee,
        int24 tickSpacing,
        bool active,
        IPositionAdapter positionAdapter,
        IRewardAdapter rewardAdapter
    );
    function owner() external view returns (address);
    function treasury() external view returns (address);
    function performanceFeeBps() external view returns (uint256);
    function referralFeeBps() external view returns (uint256);
    function referrer(address user) external view returns (address);
    function feeExempt(address user) external view returns (bool);
}

/// @title StakingManager
/// @notice Manages gauge staking operations and fee compounding for SnuggleVault
/// @dev Deployed separately to reduce SnuggleVault bytecode size
contract StakingManager {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event PositionStaked(uint256 indexed tokenId, address indexed stakingContract);
    event PositionUnstaked(uint256 indexed tokenId, address indexed stakingContract);
    event StakingRewardsClaimed(uint256 indexed tokenId, address indexed owner, address indexed rewardToken, uint256 amount);
    event StakeFailed(uint256 indexed tokenId, bytes reason);
    event UnstakeFailed(uint256 indexed tokenId, bytes reason);

    // Fee compounding events
    event FeesCompounded(uint256 indexed tokenId, address indexed owner, uint256 amount0, uint256 amount1);
    event FeesHarvestedDirect(uint256 indexed tokenId, address indexed owner, uint256 amount0, uint256 amount1);
    event ProtocolFeesDistributed(uint256 indexed tokenId, uint256 treasury0, uint256 treasury1, uint256 referral0, uint256 referral1);

    // Referral tracker events
    event ReferralTrackerUpdated(address indexed oldTracker, address indexed newTracker);

    // ═══════════════════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    error OnlyVault();
    error NotVaultOwner();
    error InvalidAddress();
    error PositionDoesNotExist();
    error NoRewardAdapter();
    error TreasuryNotSet();
    error NotPositionOwner();
    error PoolNotActive();

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Basis points denominator
    uint256 private constant BPS_DENOMINATOR = 10000;

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice The vault that owns this manager
    address public immutable vault;

    /// @notice Helper contract that has vault approval for fee transfers
    FeeTransferHelper public feeTransferHelper;

    /// @notice Referral tracker for recording referral earnings
    ReferralTracker public referralTracker;

    // ═══════════════════════════════════════════════════════════════════════════
    // MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════════

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    constructor(address _vault) {
        if (_vault == address(0)) revert InvalidAddress();
        // L-6 fix: Verify vault is a contract
        if (_vault.code.length == 0) revert InvalidAddress();
        vault = _vault;
    }

    /// @notice Set the fee transfer helper (has vault approval for transfers)
    /// @param _helper The FeeTransferHelper contract address
    function setFeeTransferHelper(address _helper) external {
        if (msg.sender != ISnuggleVaultMinimal(vault).owner()) revert NotVaultOwner();
        if (_helper == address(0)) revert InvalidAddress();
        feeTransferHelper = FeeTransferHelper(_helper);
    }

    /// @notice Set the referral tracker for recording referral earnings
    /// @param _tracker The ReferralTracker contract address (can be address(0) to disable)
    function setReferralTracker(address _tracker) external {
        if (msg.sender != ISnuggleVaultMinimal(vault).owner()) revert NotVaultOwner();
        emit ReferralTrackerUpdated(address(referralTracker), _tracker);
        referralTracker = ReferralTracker(_tracker);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // STAKING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Attempt to stake a position in reward adapter (gauge)
    /// @param tokenId Position NFT token ID
    /// @param rewardAdapter The reward adapter to stake in
    /// @param pool The pool address
    function tryStake(
        uint256 tokenId,
        IRewardAdapter rewardAdapter,
        IPositionAdapter, // unused - kept for interface compatibility
        address pool
    ) external onlyVault {
        // Skip if no reward adapter configured
        if (address(rewardAdapter) == address(0)) return;

        // Note: Vault has already called setApprovalForAll(rewardAdapter, true) on the
        // NFT manager during addPool(). The reward adapter can then call approve(gauge, tokenId)
        // because it's an approved operator. We don't need to call approve() here - and we
        // can't anyway since StakingManager is not the NFT owner or an approved operator.

        // Forward explicit gas to handle Aerodrome's complex gauge deposit operations
        try rewardAdapter.stake{gas: 1000000}(tokenId) {
            address stakingContract = rewardAdapter.getStakingContract(pool);
            emit PositionStaked(tokenId, stakingContract);
        } catch (bytes memory reason) {
            emit StakeFailed(tokenId, reason);
        }
    }

    /// @notice Attempt to unstake a position from reward adapter (gauge)
    /// @param tokenId Position NFT token ID
    /// @param rewardAdapter The reward adapter
    /// @param pool The pool address
    /// @param recipient Address to receive rewards (vault for fee extraction, or user for direct)
    /// @return rewardsEarned Amount of reward tokens claimed (AERO/CAKE)
    /// @return fees0 Amount of token0 trading fees collected during unstake (PancakeSwap only)
    /// @return fees1 Amount of token1 trading fees collected during unstake (PancakeSwap only)
    function tryUnstake(
        uint256 tokenId,
        IRewardAdapter rewardAdapter,
        address pool,
        address recipient
    ) external onlyVault returns (uint256 rewardsEarned, uint256 fees0, uint256 fees1) {
        // Skip if no reward adapter or not staked
        if (address(rewardAdapter) == address(0)) return (0, 0, 0);
        if (!rewardAdapter.isStaked(tokenId)) return (0, 0, 0);

        // Try to claim rewards first
        // Forward explicit gas to handle Aerodrome's complex gauge operations
        try rewardAdapter.claimRewards{gas: 1000000}(tokenId, recipient) returns (uint256 earned, uint256 f0, uint256 f1) {
            rewardsEarned = earned;
            fees0 = f0;
            fees1 = f1;
            if (earned > 0) {
                emit StakingRewardsClaimed(tokenId, recipient, rewardAdapter.rewardToken(), earned);
            }
        } catch {
            // Claim failed - continue with unstake
        }

        // V16-L-01 fix: Track reward token balance before/after unstake to capture
        // auto-claimed rewards (PancakeSwap MasterChef auto-harvests CAKE during withdraw).
        // If claimRewards failed, these auto-claimed rewards would otherwise bypass the
        // performance fee pipeline.
        address rewardTokenAddr = rewardAdapter.rewardToken();
        uint256 rewardBalanceBefore = IERC20(rewardTokenAddr).balanceOf(recipient);

        // Unstake the position
        // Forward explicit gas to handle Aerodrome's complex gauge withdraw operations
        try rewardAdapter.unstake{gas: 1000000}(tokenId) {
            address stakingContract = rewardAdapter.getStakingContract(pool);
            emit PositionUnstaked(tokenId, stakingContract);
        } catch (bytes memory reason) {
            emit UnstakeFailed(tokenId, reason);
        }

        // V16-L-01 fix: Capture any auto-claimed rewards that arrived at recipient during unstake
        uint256 rewardBalanceAfter = IERC20(rewardTokenAddr).balanceOf(recipient);
        if (rewardBalanceAfter > rewardBalanceBefore) {
            rewardsEarned += rewardBalanceAfter - rewardBalanceBefore;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PUBLIC STAKING FUNCTION (moved from SnuggleVault to reduce bytecode)
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Stake a position in the reward adapter (gauge)
    /// @dev V17-L-01: Restricted to position owner to prevent unwanted re-staking
    /// @param tokenId The position to stake
    function stakePosition(uint256 tokenId) external {
        // Get position data from vault
        (
            ,              // tokenId
            bytes32 poolId,
            address owner,
            ,              // rangeWidthBps
            ,              // currentTickLower
            ,              // currentTickUpper
            ,              // autoSnuggleEnabled
            ,              // autoCompoundEnabled
            ,              // rebalanceDelay
            ,              // outOfRangeSince
            ,              // totalRebalances
            ,              // lastRebalanceTime
            ,              // depositTimestamp
            ,              // cumulativeFees0
            ,              // cumulativeFees1
            ,              // cumulativeRewards
                           // __reserved
        ) = ISnuggleVaultMinimal(vault).positions(tokenId);

        if (owner == address(0)) revert PositionDoesNotExist();
        if (msg.sender != owner) revert NotPositionOwner();

        // Get reward adapter from pool config
        (
            address pool,
            ,              // token0
            ,              // token1
            ,              // fee
            ,              // tickSpacing
            bool active,
            ,              // positionAdapter
            IRewardAdapter rewardAdapter
        ) = ISnuggleVaultMinimal(vault).approvedPools(poolId);

        // V19-I-04: Verify pool is still active before allowing re-staking
        if (!active) revert PoolNotActive();
        if (address(rewardAdapter) == address(0)) revert NoRewardAdapter();

        // Stake via adapter with try-catch for robustness (M-1 fix)
        // Forward explicit gas to handle Aerodrome's complex gauge deposit operations
        try rewardAdapter.stake{gas: 1000000}(tokenId) {
            emit PositionStaked(tokenId, rewardAdapter.getStakingContract(pool));
        } catch (bytes memory reason) {
            emit StakeFailed(tokenId, reason);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // FEE COMPOUNDING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Process collected trading fees - compound matching token, harvest other
    /// @dev Called by vault during snuggle rebalance. Reads position data from vault.
    /// @param tokenId Position token ID
    /// @param token0 First token address
    /// @param token1 Second token address
    /// @param fees0 Amount of token0 fees collected
    /// @param fees1 Amount of token1 fees collected
    /// @param currentTick Current pool tick
    /// @return compound0 Amount of token0 to compound back into liquidity
    /// @return compound1 Amount of token1 to compound back into liquidity
    function processFeesForCompounding(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 fees0,
        uint256 fees1,
        int24 currentTick
    ) external onlyVault returns (uint256 compound0, uint256 compound1) {
        if (fees0 == 0 && fees1 == 0) return (0, 0);

        // Read position data from vault
        (,, address positionOwner,, int24 tickLower, int24 tickUpper,, bool autoCompoundEnabled,,,,,,,,,) =
            ISnuggleVaultMinimal(vault).positions(tokenId);

        if (!autoCompoundEnabled) {
            _harvestAllFees(tokenId, token0, token1, fees0, fees1, positionOwner);
            return (0, 0);
        }

        // Determine position side
        bool isToken0Position = currentTick < tickLower;
        bool isToken1Position = currentTick >= tickUpper;

        if (!isToken0Position && !isToken1Position) {
            _harvestAllFees(tokenId, token0, token1, fees0, fees1, positionOwner);
            return (0, 0);
        }

        if (isToken0Position) {
            // Compound all token0 fees, harvest all token1 fees
            compound0 = fees0;
            // V20-GAS-01: Combined duplicate if-check
            if (fees1 > 0) {
                feeTransferHelper.transferFromVault(token1, positionOwner, fees1);
                emit FeesHarvestedDirect(tokenId, positionOwner, 0, fees1);
            }
        } else {
            // Compound all token1 fees, harvest all token0 fees
            compound1 = fees1;
            // V20-GAS-01: Combined duplicate if-check
            if (fees0 > 0) {
                feeTransferHelper.transferFromVault(token0, positionOwner, fees0);
                emit FeesHarvestedDirect(tokenId, positionOwner, fees0, 0);
            }
        }

        if (compound0 > 0 || compound1 > 0) emit FeesCompounded(tokenId, positionOwner, compound0, compound1);
    }

    /// @notice Distribute performance fees on trading fee earnings (token0/token1 pair)
    /// @dev Reads fee config from vault. Takes performanceFeeBps% of earnings, splits between treasury and referrer.
    /// @param tokenId Position token ID
    /// @param token0 First token address
    /// @param token1 Second token address
    /// @param earned0 Token0 earnings to take performance fee from
    /// @param earned1 Token1 earnings to take performance fee from
    /// @param positionOwner Position owner
    /// @return remaining0 Token0 remaining after performance fee
    /// @return remaining1 Token1 remaining after performance fee
    function distributePerformanceFees(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 earned0,
        uint256 earned1,
        address positionOwner
    ) external onlyVault returns (uint256 remaining0, uint256 remaining1) {
        if (earned0 == 0 && earned1 == 0) return (0, 0);

        // Read config from vault to save calldata in vault bytecode
        ISnuggleVaultMinimal v = ISnuggleVaultMinimal(vault);
        address treasuryAddr = v.treasury();
        if (treasuryAddr == address(0)) revert TreasuryNotSet();

        if (v.feeExempt(positionOwner)) {
            return (earned0, earned1);
        }

        uint256 feeBps = v.performanceFeeBps();
        uint256 fee0 = (earned0 * feeBps) / BPS_DENOMINATOR;
        uint256 fee1 = (earned1 * feeBps) / BPS_DENOMINATOR;

        uint256 treasury0 = fee0;
        uint256 treasury1 = fee1;

        address positionReferrer = v.referrer(positionOwner);
        if (positionReferrer != address(0)) {
            uint256 referralFeeBps = v.referralFeeBps();
            if (referralFeeBps > 0) {
                uint256 referral0 = (earned0 * referralFeeBps) / BPS_DENOMINATOR;
                uint256 referral1 = (earned1 * referralFeeBps) / BPS_DENOMINATOR;
                // L-01 fix: Defensive check to prevent underflow
                if (referral0 > fee0) referral0 = fee0;
                if (referral1 > fee1) referral1 = fee1;
                treasury0 = fee0 - referral0;
                treasury1 = fee1 - referral1;

                if (referral0 > 0) {
                    _safeTransferReferral(token0, positionReferrer, positionOwner, referral0, treasuryAddr);
                }
                if (referral1 > 0) {
                    _safeTransferReferral(token1, positionReferrer, positionOwner, referral1, treasuryAddr);
                }
            }
        }

        if (treasury0 > 0) {
            feeTransferHelper.transferFromVault(token0, treasuryAddr, treasury0);
        }
        if (treasury1 > 0) {
            feeTransferHelper.transferFromVault(token1, treasuryAddr, treasury1);
        }

        remaining0 = earned0 - fee0;
        remaining1 = earned1 - fee1;

        emit ProtocolFeesDistributed(tokenId, treasury0, treasury1, fee0 - treasury0, fee1 - treasury1);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @dev Harvest all fees to user (no compounding)
    function _harvestAllFees(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 fees0,
        uint256 fees1,
        address positionOwner
    ) internal {
        if (fees0 > 0) {
            feeTransferHelper.transferFromVault(token0, positionOwner, fees0);
        }
        if (fees1 > 0) {
            feeTransferHelper.transferFromVault(token1, positionOwner, fees1);
        }
        emit FeesHarvestedDirect(tokenId, positionOwner, fees0, fees1);
    }

    /// @dev Safe transfer to referrer with fallback to treasury
    /// @dev Also records referral relationship and earnings to ReferralTracker if configured
    function _safeTransferReferral(
        address token,
        address referrerAddr,
        address userAddr,
        uint256 amount,
        address treasuryAddr
    ) internal {
        bool transferSuccess = true;
        try feeTransferHelper.transferFromVault(token, referrerAddr, amount) {}
        catch {
            feeTransferHelper.transferFromVault(token, treasuryAddr, amount);
            transferSuccess = false;
        }

        // Record to tracker (only if transfer to referrer succeeded)
        if (transferSuccess && address(referralTracker) != address(0)) {
            // Record the referral relationship (idempotent - will skip if already recorded)
            try referralTracker.recordReferral(userAddr) {}
            catch {
                // Already recorded or other non-critical error
            }
            // Record the earnings
            try referralTracker.recordEarnings(referrerAddr, token, amount) {}
            catch {
                // Recording failed - not critical, continue
            }
        }
    }
}

src/ReferralTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ISnuggleVaultReferral
/// @notice Minimal interface for reading referral data from SnuggleVault
interface ISnuggleVaultReferral {
    function referrer(address user) external view returns (address);
    function owner() external view returns (address);
}

/// @title ReferralTracker
/// @notice Tracks referral relationships and earnings for the Snuggle protocol
/// @dev Reads referrer data from vault's public mapping, tracks earnings via StakingManager calls
/// @author Snuggle (snuggle.fi)
contract ReferralTracker {
    // ═══════════════════════════════════════════════════════════════════════════
    // IMMUTABLES
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice The SnuggleVault contract
    ISnuggleVaultReferral public immutable vault;

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Authorized address that can record earnings (StakingManager)
    address public earningsRecorder;

    /// @notice Referrer => list of users they referred
    mapping(address => address[]) public referrals;

    /// @notice User => index in referrer's array (1-indexed, 0 means not recorded)
    mapping(address => uint256) public userReferralIndex;

    /// @notice Referrer => token => total earnings
    mapping(address => mapping(address => uint256)) public referralEarnings;

    /// @notice Referrer => list of tokens they've earned
    mapping(address => address[]) public earnedTokens;

    /// @notice Referrer => token => whether token is in earnedTokens array
    mapping(address => mapping(address => bool)) public hasEarnedToken;

    // ═══════════════════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    error NoReferrer();
    error AlreadyRecorded();
    error NotAuthorized();
    error InvalidAddress();

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event ReferralRecorded(address indexed referrer, address indexed user);
    event EarningsRecorded(address indexed referrer, address indexed token, uint256 amount, uint256 totalEarnings);
    event EarningsRecorderUpdated(address indexed oldRecorder, address indexed newRecorder);

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Initialize the tracker
    /// @param _vault The SnuggleVault address
    constructor(address _vault) {
        if (_vault == address(0)) revert InvalidAddress();
        vault = ISnuggleVaultReferral(_vault);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Set the address authorized to record earnings (typically StakingManager)
    /// @param _recorder The new earnings recorder address
    function setEarningsRecorder(address _recorder) external {
        if (msg.sender != vault.owner()) revert NotAuthorized();
        emit EarningsRecorderUpdated(earningsRecorder, _recorder);
        earningsRecorder = _recorder;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // RECORDING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Record a referral relationship
    /// @dev Anyone can call this - it reads the referrer from the vault
    /// @param user The user who was referred
    function recordReferral(address user) external {
        // Check if already recorded
        if (userReferralIndex[user] != 0) revert AlreadyRecorded();

        // Get referrer from vault
        address ref = vault.referrer(user);
        if (ref == address(0)) revert NoReferrer();

        // Record the relationship
        referrals[ref].push(user);
        userReferralIndex[user] = referrals[ref].length; // 1-indexed

        emit ReferralRecorded(ref, user);
    }

    /// @notice Record referral earnings
    /// @dev Only callable by the authorized earnings recorder (StakingManager)
    /// @param referrer The referrer who earned
    /// @param token The token earned
    /// @param amount The amount earned
    function recordEarnings(address referrer, address token, uint256 amount) external {
        if (msg.sender != earningsRecorder) revert NotAuthorized();
        if (amount == 0) return;

        // Track token if not already tracked for this referrer
        if (!hasEarnedToken[referrer][token]) {
            earnedTokens[referrer].push(token);
            hasEarnedToken[referrer][token] = true;
        }

        // Accumulate earnings
        referralEarnings[referrer][token] += amount;

        emit EarningsRecorded(referrer, token, amount, referralEarnings[referrer][token]);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Get the number of users referred by a referrer
    /// @param referrer The referrer address
    /// @return count Number of referred users
    function getReferralCount(address referrer) external view returns (uint256 count) {
        return referrals[referrer].length;
    }

    /// @notice Get all users referred by a referrer
    /// @param referrer The referrer address
    /// @return users Array of referred user addresses
    function getReferrals(address referrer) external view returns (address[] memory users) {
        return referrals[referrer];
    }

    /// @notice Get referred users with pagination
    /// @param referrer The referrer address
    /// @param offset Starting index
    /// @param limit Maximum number to return
    /// @return users Array of referred user addresses
    /// @return hasMore Whether there are more users beyond this batch
    function getReferralsPaginated(
        address referrer,
        uint256 offset,
        uint256 limit
    ) external view returns (address[] memory users, bool hasMore) {
        address[] storage allReferrals = referrals[referrer];
        uint256 total = allReferrals.length;

        if (offset >= total) {
            return (new address[](0), false);
        }

        uint256 remaining = total - offset;
        uint256 count = remaining < limit ? remaining : limit;
        hasMore = remaining > limit;

        users = new address[](count);
        for (uint256 i = 0; i < count; i++) {
            users[i] = allReferrals[offset + i];
        }
    }

    /// @notice Get total earnings for a referrer across all tokens
    /// @param referrer The referrer address
    /// @return tokens Array of token addresses
    /// @return amounts Array of earnings amounts (matching indices with tokens)
    function getAllEarnings(address referrer) external view returns (
        address[] memory tokens,
        uint256[] memory amounts
    ) {
        tokens = earnedTokens[referrer];
        amounts = new uint256[](tokens.length);

        for (uint256 i = 0; i < tokens.length; i++) {
            amounts[i] = referralEarnings[referrer][tokens[i]];
        }
    }

    /// @notice Get earnings for a specific token
    /// @param referrer The referrer address
    /// @param token The token address
    /// @return amount Total earnings in that token
    function getEarnings(address referrer, address token) external view returns (uint256 amount) {
        return referralEarnings[referrer][token];
    }

    /// @notice Check if a user's referral has been recorded
    /// @param user The user address
    /// @return recorded Whether the referral has been recorded
    /// @return referrer The referrer address (if recorded)
    function isReferralRecorded(address user) external view returns (bool recorded, address referrer) {
        recorded = userReferralIndex[user] != 0;
        if (recorded) {
            referrer = vault.referrer(user);
        }
    }

    /// @notice Get summary stats for a referrer
    /// @param referrer The referrer address
    /// @return totalReferrals Number of users referred
    /// @return totalTokensEarned Number of different tokens earned
    function getReferrerStats(address referrer) external view returns (
        uint256 totalReferrals,
        uint256 totalTokensEarned
    ) {
        totalReferrals = referrals[referrer].length;
        totalTokensEarned = earnedTokens[referrer].length;
    }
}

src/FeeTransferHelper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IPositionAdapter.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title FeeTransferHelper
/// @notice Enables StakingManager to transfer earned fees from the vault to treasury/referrers
/// @dev M-03 ARCHITECTURE NOTE — Phantom Pool Pattern:
///
///      PROBLEM: StakingManager needs to move tokens OUT of the vault (performance fees to
///      treasury, referral fees to referrers). But the vault's tokens sit in the vault contract
///      itself, and the vault has no generic `transferToken()` function to keep the attack surface
///      small. The vault only grants ERC20 approvals through `addPool()`.
///
///      SOLUTION: FeeTransferHelper implements IPositionAdapter so it can be registered via
///      addPool(). When addPool() is called with this contract as the adapter, the vault calls:
///        IERC20(token0).approve(address(this), type(uint256).max)
///        IERC20(token1).approve(address(this), type(uint256).max)
///      This gives the helper transferFrom rights on vault tokens. The helper then exposes a
///      single function `transferFromVault()` callable only by StakingManager.
///
///      WHY NOT ADD approveHelper() TO THE VAULT?  Adding a new approval function to the vault
///      would increase bytecode (vault is near 24KB limit) and create a new admin-controlled
///      approval vector. Reusing addPool() leverages existing, audited approval logic.
///
///      WHY NOT APPROVE StakingManager DIRECTLY?  StakingManager is upgradeable (can be replaced
///      via setStakingManager). The helper is immutable and acts as a narrow permission bridge.
///
///      SECURITY:
///      - Only StakingManager can call transferFromVault() — enforced by msg.sender check
///      - StakingManager is onlyVault-gated — only the vault can trigger fee distributions
///      - All IPositionAdapter functions revert NotImplemented() — the phantom pool cannot be
///        used for deposits, withdrawals, or any position management
///      - The phantom pool appears in poolIds[] but has no real liquidity or positions
///
///      V19-I-06 DEPLOYMENT SEQUENCE (required for fee compounding to work):
///      1. Deploy SnuggleVaultUpgradeable (proxy + implementation + initialize)
///      2. Deploy FeeTransferHelper(vault, stakingManager, referenceAdapter)
///      3. Deploy StakingManager(vault, feeTransferHelper)
///      4. Call satellite.addPool() with FeeTransferHelper as positionAdapter (registers phantom pool)
///      5. Call satellite.setInitialStakingManager(stakingManager)
///      If step 4 is missed, StakingManager.processFeesForCompounding() will fail on transferFromVault().
contract FeeTransferHelper is IPositionAdapter {
    using SafeERC20 for IERC20;

    address public immutable vault;
    address public immutable stakingManager;

    // Store a real pool address to pass addPool validation
    address public immutable referencePool;
    address public immutable referencePositionManager;
    int24 public immutable referenceTickSpacing;

    error OnlyStakingManager();
    error NotImplemented();
    error InvalidAddress();

    constructor(
        address _vault,
        address _stakingManager,
        address _referencePool,
        address _referencePositionManager,
        int24 _referenceTickSpacing
    ) {
        // V14-L-05: Validate all addresses are contracts (not EOAs)
        if (_vault.code.length == 0) revert InvalidAddress();
        if (_stakingManager.code.length == 0) revert InvalidAddress();
        if (_referencePool.code.length == 0) revert InvalidAddress();
        if (_referencePositionManager.code.length == 0) revert InvalidAddress();
        vault = _vault;
        stakingManager = _stakingManager;
        referencePool = _referencePool;
        referencePositionManager = _referencePositionManager;
        referenceTickSpacing = _referenceTickSpacing;
    }

    /// @notice Transfer tokens from vault to recipient
    /// @dev Only callable by StakingManager
    function transferFromVault(
        address token,
        address to,
        uint256 amount
    ) external {
        if (msg.sender != stakingManager) revert OnlyStakingManager();
        IERC20(token).safeTransferFrom(vault, to, amount);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // IPositionAdapter STUBS — Required to pass addPool() validation.
    // These are never called in production. All revert NotImplemented().
    // getPool() and getTickSpacing() return real values so addPool() succeeds.
    // ═══════════════════════════════════════════════════════════════════════════

    function getPool(address, address, uint24) external view override returns (address) {
        return referencePool; // Return real pool to pass validation
    }

    function getTickSpacing(address) external view override returns (int24) {
        return referenceTickSpacing;
    }

    function getCurrentTick(address) external pure override returns (int24) {
        revert NotImplemented();
    }

    function getTWAPTick(address, uint32) external pure override returns (int24) {
        revert NotImplemented();
    }

    function mint(address, address, uint24, int24, int24, uint256, uint256, uint256, uint256, address, uint256)
        external pure override returns (uint256, uint128, uint256, uint256)
    {
        revert NotImplemented();
    }

    function decreaseLiquidity(uint256, uint128, uint256, uint256, uint256)
        external pure override returns (uint256, uint256)
    {
        revert NotImplemented();
    }

    function collect(uint256, address) external pure override returns (uint256, uint256) {
        revert NotImplemented();
    }

    function burn(uint256) external pure override {
        revert NotImplemented();
    }

    function getPosition(uint256) external pure override returns (address, address, uint24, int24, int24, uint128) {
        revert NotImplemented();
    }

    function positionManager() external view override returns (address) {
        return referencePositionManager;
    }

    function approvePosition(uint256) external pure override {
        revert NotImplemented();
    }
}

