// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title SnuggleLogic
/// @notice Library for fee calculations and parameter validation in SnuggleVault
/// @dev Extracted to reduce main contract size below EVM bytecode limit
library SnuggleLogic {
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MIN_REBALANCE_DELAY = 0;
    uint256 public constant MAX_REBALANCE_DELAY = 7 days;

    /// @notice Result of fee calculations
    struct FeeResult {
        uint256 protocolFee0;
        uint256 protocolFee1;
        uint256 referralFee0;
        uint256 referralFee1;
        uint256 treasuryFee0;
        uint256 treasuryFee1;
        uint256 remaining0;
        uint256 remaining1;
    }

    /// @notice Validation bounds for parameters
    struct ValidationBounds {
        uint24 minRangeWidthBps;
        uint24 maxRangeWidthBps;
    }

    error InvalidRangeWidth();
    error InvalidRebalanceDelay();

    /// @notice Calculate all fee components for a performance fee on earnings
    /// @param amount0 Total amount of token0 earnings
    /// @param amount1 Total amount of token1 earnings
    /// @param performanceFeeBps Performance fee in basis points (e.g. 1500 = 15%)
    /// @param referralFeeBps Referral fee in basis points
    /// @param hasReferrer Whether user has a referrer
    /// @param isExempt Whether user is fee exempt
    /// @return result Struct containing all fee amounts and remaining
    function calculateFees(
        uint256 amount0,
        uint256 amount1,
        uint256 performanceFeeBps,
        uint256 referralFeeBps,
        bool hasReferrer,
        bool isExempt
    ) internal pure returns (FeeResult memory result) {
        if (isExempt) {
            // No fees - all amounts remain
            result.remaining0 = amount0;
            result.remaining1 = amount1;
            return result;
        }

        // Calculate performance fees on earnings
        result.protocolFee0 = (amount0 * performanceFeeBps) / BPS_DENOMINATOR;
        result.protocolFee1 = (amount1 * performanceFeeBps) / BPS_DENOMINATOR;

        if (hasReferrer && referralFeeBps > 0) {
            // Calculate referral portion (comes out of protocol fee)
            result.referralFee0 = (amount0 * referralFeeBps) / BPS_DENOMINATOR;
            result.referralFee1 = (amount1 * referralFeeBps) / BPS_DENOMINATOR;

            // L-05 fix: Defensive check to prevent underflow if referralFeeBps >= performanceFeeBps
            if (result.referralFee0 > result.protocolFee0) result.referralFee0 = result.protocolFee0;
            if (result.referralFee1 > result.protocolFee1) result.referralFee1 = result.protocolFee1;

            // Treasury gets remainder of protocol fee
            result.treasuryFee0 = result.protocolFee0 - result.referralFee0;
            result.treasuryFee1 = result.protocolFee1 - result.referralFee1;
        } else {
            // No referrer - all protocol fees to treasury
            result.treasuryFee0 = result.protocolFee0;
            result.treasuryFee1 = result.protocolFee1;
        }

        // Calculate remaining amounts after fees
        result.remaining0 = amount0 - result.protocolFee0;
        result.remaining1 = amount1 - result.protocolFee1;
    }

    /// @notice Calculate slippage minimums
    /// @param amount0 Desired amount of token0
    /// @param amount1 Desired amount of token1
    /// @param slippageBps Slippage tolerance in basis points
    /// @return amount0Min Minimum acceptable amount of token0
    /// @return amount1Min Minimum acceptable amount of token1
    function calculateSlippageMinimums(
        uint256 amount0,
        uint256 amount1,
        uint256 slippageBps
    ) internal pure returns (uint256 amount0Min, uint256 amount1Min) {
        amount0Min = (amount0 * (BPS_DENOMINATOR - slippageBps)) / BPS_DENOMINATOR;
        amount1Min = (amount1 * (BPS_DENOMINATOR - slippageBps)) / BPS_DENOMINATOR;
    }

    /// @notice Validate range width and rebalance delay parameters
    /// @param rangeWidthBps Range width in basis points
    /// @param rebalanceDelay Rebalance delay in seconds
    /// @param bounds Validation bounds
    function validateParameters(
        uint24 rangeWidthBps,
        uint256 rebalanceDelay,
        ValidationBounds memory bounds
    ) internal pure {
        if (rangeWidthBps < bounds.minRangeWidthBps ||
            rangeWidthBps > bounds.maxRangeWidthBps) {
            revert InvalidRangeWidth();
        }
        // V17-L-05: MIN_REBALANCE_DELAY check is currently always false (MIN=0, uint256 >= 0),
        // but retained as a safety guard in case MIN_REBALANCE_DELAY is increased in a future version.
        if (rebalanceDelay < MIN_REBALANCE_DELAY ||
            rebalanceDelay > MAX_REBALANCE_DELAY) {
            revert InvalidRebalanceDelay();
        }
    }

    /// @notice Check if position is out of range
    /// @param currentTick Current pool tick
    /// @param tickLower Position lower tick
    /// @param tickUpper Position upper tick
    /// @return True if position is out of range
    function isOutOfRange(
        int24 currentTick,
        int24 tickLower,
        int24 tickUpper
    ) internal pure returns (bool) {
        return currentTick < tickLower || currentTick >= tickUpper;
    }

    /// @notice Calculate dust amounts after minting
    /// @param remaining0 Remaining amount of token0 before mint
    /// @param remaining1 Remaining amount of token1 before mint
    /// @param used0 Amount of token0 used in mint
    /// @param used1 Amount of token1 used in mint
    /// @return dust0 Dust amount of token0
    /// @return dust1 Dust amount of token1
    function calculateDust(
        uint256 remaining0,
        uint256 remaining1,
        uint256 used0,
        uint256 used1
    ) internal pure returns (uint256 dust0, uint256 dust1) {
        dust0 = remaining0 - used0;
        dust1 = remaining1 - used1;
    }

    /// @notice Saturating add for uint128 (prevents overflow revert)
    /// @param a First value
    /// @param b Second value (uint256 for flexibility)
    /// @return Result capped at uint128 max
    function saturatingAdd128(uint128 a, uint256 b) internal pure returns (uint128) {
        uint256 sum = uint256(a) + b;
        if (sum > type(uint128).max) {
            return type(uint128).max;
        }
        return uint128(sum);
    }

    /// @notice Select the more conservative tick for single-sided deposits
    /// @param twapTick TWAP tick
    /// @param spotTick Spot tick
    /// @param isToken0 Whether depositing token0
    /// @return currentTick The more conservative tick
    function selectConservativeTick(
        int24 twapTick,
        int24 spotTick,
        bool isToken0
    ) internal pure returns (int24 currentTick) {
        // For token0 deposits (range ABOVE current), use the higher tick
        // For token1 deposits (range BELOW current), use the lower tick
        currentTick = isToken0
            ? (twapTick > spotTick ? twapTick : spotTick)
            : (twapTick < spotTick ? twapTick : spotTick);
    }

    /// @notice Check if minimum hold time has passed
    /// @param depositTimestamp When position was deposited
    /// @param minHoldTime Minimum required hold time
    /// @return True if hold time requirement is met
    function isHoldTimeElapsed(
        uint64 depositTimestamp,
        uint256 minHoldTime
    ) internal view returns (bool) {
        return block.timestamp >= depositTimestamp + minHoldTime;
    }
}

src/libraries/SnuggleRebalanceLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IPositionAdapter.sol";
import "../interfaces/IRewardAdapter.sol";
import "../StakingManager.sol";
import "./TickMath.sol";
import "./SnuggleLogic.sol";

/// @title SnuggleRebalanceLib
/// @notice Library for rebalance and fee distribution logic, deployed separately to reduce vault bytecode
/// @dev Public functions are called via delegatecall, preserving vault's storage context
library SnuggleRebalanceLib {
    using SafeERC20 for IERC20;

    uint256 internal constant BPS_DENOMINATOR = 10000;

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS (redefined for delegatecall context — emitted as vault events)
    // ═══════════════════════════════════════════════════════════════════════════

    event FeesHarvested(uint256 indexed tokenId, address indexed owner, uint256 fees0, uint256 fees1);
    event RebalanceSkipped(uint256 indexed tokenId, int24 tickLower, int24 tickUpper, string reason);
    event PerformanceFeeCollected(uint256 indexed tokenId, address indexed token, uint256 feeAmount, uint256 treasuryAmount, uint256 referralAmount);
    event ReferralPaymentFailed(address indexed referrer, address indexed token, uint256 amount);
    event StakingRewardsClaimed(uint256 indexed tokenId, address indexed owner, address indexed rewardToken, uint256 amount);

    // ═══════════════════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    error PositionInRange();
    error RebalanceWouldNotChangeRange();

    // ═══════════════════════════════════════════════════════════════════════════
    // STRUCTS
    // ═══════════════════════════════════════════════════════════════════════════

    struct RebalanceContext {
        // Position data
        address posOwner;
        bytes32 poolId;
        uint24 rangeWidthBps;
        int24 currentTickLower;
        int24 currentTickUpper;
        bool autoCompoundEnabled;
        uint32 totalRebalances;
        uint128 cumulativeFees0;
        uint128 cumulativeFees1;
        uint128 cumulativeRewards;
        // Pool config
        address pool;
        address token0;
        address token1;
        uint24 fee;
        int24 tickSpacing;
        IPositionAdapter adapter;
        IRewardAdapter rewardAdapter;
        // Vault config
        uint32 twapInterval;
        uint256 slippageBps;
        uint256 performanceFeeBps;
        uint256 referralFeeBps;
        address treasury;
        StakingManager stakingManager;
        bool isExempt;
        address referrerAddr;
        // Pre-computed unstake results (vault unstakes before calling)
        uint256 rewardsEarned;
        uint256 unstakeFees0;
        uint256 unstakeFees1;
    }

    struct RebalanceResult {
        uint256 newTokenId;
        int24 newTickLower;
        int24 newTickUpper;
        uint256 perfFee0;
        uint256 perfFee1;
        uint128 updatedCumulativeFees0;
        uint128 updatedCumulativeFees1;
        uint128 updatedCumulativeRewards;
        bool skipped;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // DEPOSIT MINT (moved from vault to eliminate duplicate TickMath inlining)
    // ═══════════════════════════════════════════════════════════════════════════

    error TWAPSpotDivergence();

    struct MintContext {
        address pool;
        address token0;
        address token1;
        uint24 fee;
        int24 tickSpacing;
        IPositionAdapter adapter;
        uint256 actualAmount0;
        uint256 actualAmount1;
        uint24 rangeWidthBps;
        bool singleSided;
        uint32 twapInterval;
        uint256 slippageBps;
    }

    struct MintResult {
        uint256 tokenId;
        int24 tickLower;
        int24 tickUpper;
        uint128 liquidity;
    }

    /// @notice Execute deposit mint — tick calculation + adapter mint + refund
    /// @dev Called via delegatecall from vault. Eliminates duplicate TickMath inlining.
    function executeMint(MintContext memory ctx, uint256 deadline) public returns (MintResult memory result) {
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Min;
        uint256 amount1Min;

        if (ctx.singleSided) {
            bool isToken0 = ctx.actualAmount0 > 0;
            int24 twapTick = ctx.adapter.getTWAPTick(ctx.pool, ctx.twapInterval);
            int24 spotTick = ctx.adapter.getCurrentTick(ctx.pool);
            int24 currentTick = SnuggleLogic.selectConservativeTick(twapTick, spotTick, isToken0);
            (tickLower, tickUpper) = TickMath.calculateSnuggleRange(
                currentTick, ctx.tickSpacing, ctx.rangeWidthBps, ctx.actualAmount0, ctx.actualAmount1
            );
            (amount0Min, amount1Min) = SnuggleLogic.calculateSlippageMinimums(
                ctx.actualAmount0, ctx.actualAmount1, ctx.slippageBps
            );
        } else {
            int24 currentTick = ctx.adapter.getTWAPTick(ctx.pool, ctx.twapInterval);
            int24 spotTick = ctx.adapter.getCurrentTick(ctx.pool);
            {
                int24 div = currentTick > spotTick ? currentTick - spotTick : spotTick - currentTick;
                if (div > ctx.tickSpacing * 10) revert TWAPSpotDivergence();
            }
            (tickLower, tickUpper) = TickMath.calculateCenteredRange(
                currentTick, ctx.tickSpacing, ctx.rangeWidthBps
            );
        }

        uint256 amount0Used;
        uint256 amount1Used;
        (result.tokenId, result.liquidity, amount0Used, amount1Used) = ctx.adapter.mint(
            ctx.token0, ctx.token1, ctx.fee,
            tickLower, tickUpper, ctx.actualAmount0, ctx.actualAmount1,
            amount0Min, amount1Min, address(this), deadline
        );
        result.tickLower = tickLower;
        result.tickUpper = tickUpper;

        // Refund unused tokens to depositor
        if (ctx.actualAmount0 > amount0Used) {
            IERC20(ctx.token0).safeTransfer(msg.sender, ctx.actualAmount0 - amount0Used);
        }
        if (ctx.actualAmount1 > amount1Used) {
            IERC20(ctx.token1).safeTransfer(msg.sender, ctx.actualAmount1 - amount1Used);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // REBALANCE
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Execute the full snuggle rebalance logic
    /// @dev Called via delegatecall from the vault — external calls appear from vault
    /// @param ctx All context needed for the rebalance (position, pool, config data)
    /// @param tokenId The position token ID
    /// @param isManual Whether this is a manual rebalance
    /// @return result The rebalance results for the vault to apply to storage
    function executeRebalance(
        RebalanceContext memory ctx,
        uint256 tokenId,
        bool isManual
    ) public returns (RebalanceResult memory result) {
        // Initialize cumulative trackers from context
        result.updatedCumulativeFees0 = ctx.cumulativeFees0;
        result.updatedCumulativeFees1 = ctx.cumulativeFees1;
        result.updatedCumulativeRewards = ctx.cumulativeRewards;

        // H-2: Use TWAP for manipulation resistance
        int24 currentTick = ctx.adapter.getTWAPTick(ctx.pool, ctx.twapInterval);

        // CRITICAL FIX: Check spot tick to prevent TWAP/spot divergence issue
        int24 spotTick = ctx.adapter.getCurrentTick(ctx.pool);
        bool spotInRange = spotTick >= ctx.currentTickLower && spotTick < ctx.currentTickUpper;

        if (spotInRange) {
            if (isManual) revert PositionInRange();
            emit RebalanceSkipped(tokenId, ctx.currentTickLower, ctx.currentTickUpper, "Spot in range");
            _handleSkippedRebalance(ctx, tokenId);
            result.skipped = true;
            // V25-L-01: Update cumulative trackers even on skipped rebalances
            _updateSkippedTrackers(ctx, result);
            return result;
        }

        // Check if rebalancing would actually change the range
        bool wouldChange = TickMath.wouldSnuggleChangeRange(
            currentTick, ctx.tickSpacing, ctx.rangeWidthBps,
            ctx.currentTickLower, ctx.currentTickUpper
        );
        if (!wouldChange) {
            if (isManual) revert RebalanceWouldNotChangeRange();
            emit RebalanceSkipped(tokenId, ctx.currentTickLower, ctx.currentTickUpper, "Range unchanged");
            _handleSkippedRebalance(ctx, tokenId);
            result.skipped = true;
            // V25-L-01: Update cumulative trackers even on skipped rebalances
            _updateSkippedTrackers(ctx, result);
            return result;
        }

        // Steps 0-2: Collect earnings and take performance fees
        (uint256 compound0, uint256 compound1) = _collectEarningsAndFees(
            ctx, tokenId, currentTick, result
        );

        // Step 3: Remove all liquidity from old position
        // I-05: Zero slippage is safe — decreaseLiquidity removes exact liquidity with no swap.
        // Amount returned is deterministic for the current tick. Slippage protection is on the mint (Step 6).
        (,,,,, uint128 liquidity) = ctx.adapter.getPosition(tokenId);
        ctx.adapter.decreaseLiquidity(tokenId, liquidity, 0, 0, block.timestamp + 1 hours);
        (uint256 amount0, uint256 amount1) = ctx.adapter.collect(tokenId, address(this));

        // Step 4: Total amounts (principal + compounded fees)
        uint256 remainingAmount0 = amount0 + compound0;
        uint256 remainingAmount1 = amount1 + compound1;

        // Step 5: Calculate new tick range
        (result.newTickLower, result.newTickUpper) = TickMath.calculateSnuggleRange(
            currentTick, ctx.tickSpacing, ctx.rangeWidthBps,
            remainingAmount0, remainingAmount1
        );

        // Step 6: Mint new position with slippage protection
        uint256 amount0Min = result.newTickLower > currentTick
            ? (remainingAmount0 * (BPS_DENOMINATOR - ctx.slippageBps)) / BPS_DENOMINATOR : 0;
        uint256 amount1Min = result.newTickUpper <= currentTick
            ? (remainingAmount1 * (BPS_DENOMINATOR - ctx.slippageBps)) / BPS_DENOMINATOR : 0;

        uint256 amount0Used;
        uint256 amount1Used;
        (result.newTokenId, , amount0Used, amount1Used) = ctx.adapter.mint(
            ctx.token0, ctx.token1, ctx.fee,
            result.newTickLower, result.newTickUpper,
            remainingAmount0, remainingAmount1,
            amount0Min, amount1Min,
            address(this), block.timestamp + 1 hours
        );

        // Step 7: Handle dust (send back to user)
        uint256 dust0 = remainingAmount0 - amount0Used;
        uint256 dust1 = remainingAmount1 - amount1Used;
        if (dust0 > 0) IERC20(ctx.token0).safeTransfer(ctx.posOwner, dust0);
        if (dust1 > 0) IERC20(ctx.token1).safeTransfer(ctx.posOwner, dust1);

        // Step 8: Burn old NFT
        ctx.adapter.burn(tokenId);
    }

    /// @dev V22-M-01: Handle skipped rebalance — re-stake position and return stranded tokens
    /// V23-M-01: Route rewards/fees through performance fee pipeline (not direct transfer)
    /// V23-L-03: Emit events for off-chain tracking
    /// @param ctx Rebalance context with all needed data
    /// @param tokenId The position token ID (still the original, since no rebalance occurred)
    function _handleSkippedRebalance(RebalanceContext memory ctx, uint256 tokenId) internal {
        // Re-stake position in gauge (vault already unstaked it before calling library)
        if (address(ctx.stakingManager) != address(0) && address(ctx.rewardAdapter) != address(0)) {
            ctx.stakingManager.tryStake(tokenId, ctx.rewardAdapter, ctx.adapter, ctx.pool);
        }
        // V23-M-01: Process staking rewards through performance fee pipeline
        if (ctx.rewardsEarned > 0 && address(ctx.rewardAdapter) != address(0)) {
            address rewardToken = ctx.rewardAdapter.rewardToken();
            uint256 remaining = distributeRewardPerformanceFee(
                tokenId, rewardToken, ctx.rewardsEarned, ctx.posOwner,
                ctx.isExempt, ctx.performanceFeeBps, ctx.referralFeeBps,
                ctx.referrerAddr, ctx.treasury
            );
            if (remaining > 0) {
                IERC20(rewardToken).safeTransfer(ctx.posOwner, remaining);
            }
            emit StakingRewardsClaimed(tokenId, ctx.posOwner, rewardToken, ctx.rewardsEarned);
        }
        // V23-M-01: Process trading fees through performance fee pipeline
        if (ctx.unstakeFees0 > 0 || ctx.unstakeFees1 > 0) {
            uint256 remaining0 = ctx.unstakeFees0;
            uint256 remaining1 = ctx.unstakeFees1;
            if (address(ctx.stakingManager) != address(0)) {
                (remaining0, remaining1) = ctx.stakingManager.distributePerformanceFees(
                    tokenId, ctx.token0, ctx.token1,
                    ctx.unstakeFees0, ctx.unstakeFees1, ctx.posOwner
                );
            }
            if (remaining0 > 0) {
                IERC20(ctx.token0).safeTransfer(ctx.posOwner, remaining0);
            }
            if (remaining1 > 0) {
                IERC20(ctx.token1).safeTransfer(ctx.posOwner, remaining1);
            }
            emit FeesHarvested(tokenId, ctx.posOwner, ctx.unstakeFees0, ctx.unstakeFees1);
        }
    }

    /// @dev V25-L-01: Update cumulative trackers for skipped rebalances
    /// @param ctx Rebalance context with earnings data
    /// @param result Rebalance result to update tracker fields on
    function _updateSkippedTrackers(RebalanceContext memory ctx, RebalanceResult memory result) internal pure {
        if (ctx.unstakeFees0 > 0 || ctx.unstakeFees1 > 0) {
            result.updatedCumulativeFees0 = SnuggleLogic.saturatingAdd128(ctx.cumulativeFees0, ctx.unstakeFees0);
            result.updatedCumulativeFees1 = SnuggleLogic.saturatingAdd128(ctx.cumulativeFees1, ctx.unstakeFees1);
        }
        if (ctx.rewardsEarned > 0) {
            result.updatedCumulativeRewards = SnuggleLogic.saturatingAdd128(ctx.cumulativeRewards, ctx.rewardsEarned);
        }
    }

    /// @dev Collect earnings (rewards + fees), take performance fees, process compounding
    function _collectEarningsAndFees(
        RebalanceContext memory ctx,
        uint256 tokenId,
        int24 currentTick,
        RebalanceResult memory result
    ) internal returns (uint256 compound0, uint256 compound1) {
        // Step 0.5: Take performance fee on staking rewards (already unstaked by vault)
        if (ctx.rewardsEarned > 0) {
            result.updatedCumulativeRewards = SnuggleLogic.saturatingAdd128(
                result.updatedCumulativeRewards, ctx.rewardsEarned
            );
            address rewardTokenAddr = ctx.rewardAdapter.rewardToken();
            uint256 remainingRewards = distributeRewardPerformanceFee(
                tokenId, rewardTokenAddr, ctx.rewardsEarned, ctx.posOwner,
                ctx.isExempt, ctx.performanceFeeBps, ctx.referralFeeBps,
                ctx.referrerAddr, ctx.treasury
            );
            if (remainingRewards > 0) {
                IERC20(rewardTokenAddr).safeTransfer(ctx.posOwner, remainingRewards);
            }
        }

        // Step 1: Collect accrued trading fees to vault
        (uint256 collectFees0, uint256 collectFees1) = ctx.adapter.collect(tokenId, address(this));

        // Combine trading fees from unstake (PancakeSwap) and collect (Uniswap/Aerodrome)
        uint256 fees0 = ctx.unstakeFees0 + collectFees0;
        uint256 fees1 = ctx.unstakeFees1 + collectFees1;

        if (fees0 > 0 || fees1 > 0) {
            result.updatedCumulativeFees0 = SnuggleLogic.saturatingAdd128(
                result.updatedCumulativeFees0, fees0
            );
            result.updatedCumulativeFees1 = SnuggleLogic.saturatingAdd128(
                result.updatedCumulativeFees1, fees1
            );
            emit FeesHarvested(tokenId, ctx.posOwner, fees0, fees1);
        }

        // Step 1.5: Take performance fee on trading fees
        uint256 remainingFees0 = fees0;
        uint256 remainingFees1 = fees1;
        if (address(ctx.stakingManager) != address(0)) {
            (remainingFees0, remainingFees1) = ctx.stakingManager.distributePerformanceFees(
                tokenId, ctx.token0, ctx.token1, fees0, fees1, ctx.posOwner
            );
        }

        result.perfFee0 = fees0 - remainingFees0;
        result.perfFee1 = fees1 - remainingFees1;

        // Step 2: Process remaining fees for compounding
        if (address(ctx.stakingManager) != address(0)) {
            (compound0, compound1) = ctx.stakingManager.processFeesForCompounding(
                tokenId, ctx.token0, ctx.token1, remainingFees0, remainingFees1, currentTick
            );
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // EARNINGS PROCESSING (shared by withdraw, harvest, claimStakingRewards)
    // ═══════════════════════════════════════════════════════════════════════════

    struct EarningsContext {
        uint256 tokenId;
        address posOwner;
        address token0;
        address token1;
        uint256 rewardsEarned;
        uint256 fees0;
        uint256 fees1;
        IRewardAdapter rewardAdapter;
        StakingManager stakingManager;
        uint256 performanceFeeBps;
        uint256 referralFeeBps;
        address referrerAddr;
        address treasury;
        bool isExempt;
        uint128 cumulativeFees0;
        uint128 cumulativeFees1;
        uint128 cumulativeRewards;
    }

    /// @notice Process all earnings (staking rewards + trading fees) with performance fees
    /// @dev Called via delegatecall from vault for withdraw, harvest, claimStakingRewards
    /// @param ctx Earnings context with all needed data
    /// @return newCumFees0 Updated cumulative fees for token0
    /// @return newCumFees1 Updated cumulative fees for token1
    /// @return newCumRewards Updated cumulative rewards
    /// @return remFees0 Trading fees sent to user (for event tracking)
    /// @return remFees1 Trading fees sent to user (for event tracking)
    function processAllEarnings(
        EarningsContext memory ctx
    ) public returns (
        uint128 newCumFees0, uint128 newCumFees1, uint128 newCumRewards,
        uint256 remFees0, uint256 remFees1
    ) {
        newCumFees0 = ctx.cumulativeFees0;
        newCumFees1 = ctx.cumulativeFees1;
        newCumRewards = ctx.cumulativeRewards;
        remFees0 = ctx.fees0;
        remFees1 = ctx.fees1;

        // Process staking rewards (AERO/CAKE)
        if (ctx.rewardsEarned > 0 && address(ctx.rewardAdapter) != address(0)) {
            newCumRewards = SnuggleLogic.saturatingAdd128(newCumRewards, ctx.rewardsEarned);
            address rewardTokenAddr = ctx.rewardAdapter.rewardToken();
            uint256 remRewards = distributeRewardPerformanceFee(
                ctx.tokenId, rewardTokenAddr, ctx.rewardsEarned, ctx.posOwner,
                ctx.isExempt, ctx.performanceFeeBps, ctx.referralFeeBps,
                ctx.referrerAddr, ctx.treasury
            );
            if (remRewards > 0) IERC20(rewardTokenAddr).safeTransfer(ctx.posOwner, remRewards);
            emit StakingRewardsClaimed(ctx.tokenId, ctx.posOwner, rewardTokenAddr, ctx.rewardsEarned);
        }

        // Process trading fees
        if (ctx.fees0 > 0 || ctx.fees1 > 0) {
            newCumFees0 = SnuggleLogic.saturatingAdd128(newCumFees0, ctx.fees0);
            newCumFees1 = SnuggleLogic.saturatingAdd128(newCumFees1, ctx.fees1);
            emit FeesHarvested(ctx.tokenId, ctx.posOwner, ctx.fees0, ctx.fees1);

            if (address(ctx.stakingManager) != address(0)) {
                (remFees0, remFees1) = ctx.stakingManager.distributePerformanceFees(
                    ctx.tokenId, ctx.token0, ctx.token1, ctx.fees0, ctx.fees1, ctx.posOwner
                );
            }
            if (remFees0 > 0) IERC20(ctx.token0).safeTransfer(ctx.posOwner, remFees0);
            if (remFees1 > 0) IERC20(ctx.token1).safeTransfer(ctx.posOwner, remFees1);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // FEE DISTRIBUTION
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Distribute performance fee on a single reward token (AERO/CAKE)
    /// @dev Public so it can be called directly from vault for withdraw/claim, or internally during rebalance
    /// @param tokenId Position token ID for event
    /// @param rewardTokenAddr The reward token address
    /// @param amount Total reward amount in vault
    /// @param posOwner Position owner
    /// @param isExempt Whether user is fee-exempt
    /// @param performanceFeeBps_ Performance fee in bps
    /// @param referralFeeBps_ Referral fee in bps
    /// @param referrerAddr Referrer address (address(0) if none)
    /// @param treasury_ Treasury address
    /// @return remaining Amount after performance fee
    function distributeRewardPerformanceFee(
        uint256 tokenId,
        address rewardTokenAddr,
        uint256 amount,
        address posOwner,
        bool isExempt,
        uint256 performanceFeeBps_,
        uint256 referralFeeBps_,
        address referrerAddr,
        address treasury_
    ) public returns (uint256 remaining) {
        if (amount == 0 || isExempt) return amount;

        uint256 fee = (amount * performanceFeeBps_) / BPS_DENOMINATOR;
        if (fee == 0) return amount;

        uint256 treasuryAmount = fee;
        uint256 referralAmount;

        if (referrerAddr != address(0) && referralFeeBps_ > 0) {
            referralAmount = (amount * referralFeeBps_) / BPS_DENOMINATOR;
            if (referralAmount > fee) referralAmount = fee;
            treasuryAmount = fee - referralAmount;
            if (referralAmount > 0) {
                // V14-L-02: Try-catch with treasury fallback
                // V19-L-01: Uses .transfer() (not .safeTransfer()) because safeTransfer is a library
                // function and cannot be used with try-catch. Both failure modes are handled:
                // - Revert → caught by catch block → treasury fallback
                // - Returns false → caught by !success check → treasury fallback
                // - No return data → ABI decode fails → caught by catch block → treasury fallback
                try IERC20(rewardTokenAddr).transfer(referrerAddr, referralAmount) returns (bool success) {
                    if (!success) {
                        IERC20(rewardTokenAddr).safeTransfer(treasury_, referralAmount);
                        emit ReferralPaymentFailed(referrerAddr, rewardTokenAddr, referralAmount);
                    }
                } catch {
                    IERC20(rewardTokenAddr).safeTransfer(treasury_, referralAmount);
                    emit ReferralPaymentFailed(referrerAddr, rewardTokenAddr, referralAmount);
                }
            }
        }

        if (treasuryAmount > 0) {
            IERC20(rewardTokenAddr).safeTransfer(treasury_, treasuryAmount);
        }

        emit PerformanceFeeCollected(tokenId, rewardTokenAddr, fee, treasuryAmount, referralAmount);
        remaining = amount - fee;
    }
}

src/StakingManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IRewardAdapter.sol";
import "./interfaces/IPositionAdapter.sol";
import "./FeeTransferHelper.sol";
import "./ReferralTracker.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Minimal vault interface for StakingManager
interface ISnuggleVaultMinimal {
    function positions(uint256 tokenId) external view returns (
        uint256 tokenId_,
        bytes32 poolId,
        address owner,
        uint24 rangeWidthBps,
        int24 currentTickLower,
        int24 currentTickUpper,
        bool autoSnuggleEnabled,
        bool autoCompoundEnabled,
        uint64 rebalanceDelay,
        uint64 outOfRangeSince,
        uint32 totalRebalances,
        uint32 lastRebalanceTime,
        uint64 depositTimestamp,
        uint128 cumulativeFees0,
        uint128 cumulativeFees1,
        uint128 cumulativeRewards,
        uint128 __reserved
    );
    function approvedPools(bytes32 poolId) external view returns (
        address pool,
        address token0,
        address token1,
        uint24 fee,
        int24 tickSpacing,
        bool active,
        IPositionAdapter positionAdapter,
        IRewardAdapter rewardAdapter
    );
    function owner() external view returns (address);
    function treasury() external view returns (address);
    function performanceFeeBps() external view returns (uint256);
    function referralFeeBps() external view returns (uint256);
    function referrer(address user) external view returns (address);
    function feeExempt(address user) external view returns (bool);
}

/// @title StakingManager
/// @notice Manages gauge staking operations and fee compounding for SnuggleVault
/// @dev Deployed separately to reduce SnuggleVault bytecode size
contract StakingManager {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════════

    event PositionStaked(uint256 indexed tokenId, address indexed stakingContract);
    event PositionUnstaked(uint256 indexed tokenId, address indexed stakingContract);
    event StakingRewardsClaimed(uint256 indexed tokenId, address indexed owner, address indexed rewardToken, uint256 amount);
    event StakeFailed(uint256 indexed tokenId, bytes reason);
    event UnstakeFailed(uint256 indexed tokenId, bytes reason);

    // Fee compounding events
    event FeesCompounded(uint256 indexed tokenId, address indexed owner, uint256 amount0, uint256 amount1);
    event FeesHarvestedDirect(uint256 indexed tokenId, address indexed owner, uint256 amount0, uint256 amount1);
    event ProtocolFeesDistributed(uint256 indexed tokenId, uint256 treasury0, uint256 treasury1, uint256 referral0, uint256 referral1);

    // Referral tracker events
    event ReferralTrackerUpdated(address indexed oldTracker, address indexed newTracker);

    // Custom referral rate events
    event CustomReferralBpsSet(address indexed referrer, uint256 bps);

    // ═══════════════════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════════════════

    error OnlyVault();
    error NotVaultOwner();
    error InvalidAddress();
    error PositionDoesNotExist();
    error NoRewardAdapter();
    error TreasuryNotSet();
    error NotPositionOwner();
    error PoolNotActive();
    error InvalidParameter();

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Basis points denominator
    uint256 private constant BPS_DENOMINATOR = 10000;

    // ═══════════════════════════════════════════════════════════════════════════
    // STATE
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice The vault that owns this manager
    address public immutable vault;

    /// @notice Helper contract that has vault approval for fee transfers
    FeeTransferHelper public feeTransferHelper;

    /// @notice Referral tracker for recording referral earnings
    ReferralTracker public referralTracker;

    /// @notice Custom referral rate overrides per referrer (0 = use global default)
    mapping(address => uint256) public customReferralBps;

    // ═══════════════════════════════════════════════════════════════════════════
    // MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════════

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════════

    constructor(address _vault) {
        if (_vault == address(0)) revert InvalidAddress();
        // L-6 fix: Verify vault is a contract
        if (_vault.code.length == 0) revert InvalidAddress();
        vault = _vault;
    }

    /// @notice Set the fee transfer helper (has vault approval for transfers)
    /// @param _helper The FeeTransferHelper contract address
    function setFeeTransferHelper(address _helper) external {
        if (msg.sender != ISnuggleVaultMinimal(vault).owner()) revert NotVaultOwner();
        if (_helper == address(0)) revert InvalidAddress();
        feeTransferHelper = FeeTransferHelper(_helper);
    }

    /// @notice Set the referral tracker for recording referral earnings
    /// @param _tracker The ReferralTracker contract address (can be address(0) to disable)
    function setReferralTracker(address _tracker) external {
        if (msg.sender != ISnuggleVaultMinimal(vault).owner()) revert NotVaultOwner();
        emit ReferralTrackerUpdated(address(referralTracker), _tracker);
        referralTracker = ReferralTracker(_tracker);
    }

    /// @notice Set a custom referral rate for a specific referrer
    /// @dev 0 = use global default from vault. Capped at current performance fee.
    ///      Also defended at runtime by clamp (referral > fee ? fee : referral).
    /// @param referrer The referrer address
    /// @param bps Custom referral rate in basis points (0 to reset to global)
    function setCustomReferralBps(address referrer, uint256 bps) external {
        if (msg.sender != ISnuggleVaultMinimal(vault).owner()) revert NotVaultOwner();
        if (referrer == address(0)) revert InvalidAddress();
        if (bps > ISnuggleVaultMinimal(vault).performanceFeeBps()) revert InvalidParameter();
        customReferralBps[referrer] = bps;
        emit CustomReferralBpsSet(referrer, bps);
    }

    /// @notice Get effective referral rate for a referrer (custom or global)
    /// @param referrer The referrer address
    /// @return bps The effective referral rate in basis points
    function getEffectiveReferralBps(address referrer) external view returns (uint256 bps) {
        bps = customReferralBps[referrer];
        if (bps == 0) bps = ISnuggleVaultMinimal(vault).referralFeeBps();
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // STAKING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Attempt to stake a position in reward adapter (gauge)
    /// @param tokenId Position NFT token ID
    /// @param rewardAdapter The reward adapter to stake in
    /// @param pool The pool address
    function tryStake(
        uint256 tokenId,
        IRewardAdapter rewardAdapter,
        IPositionAdapter, // unused - kept for interface compatibility
        address pool
    ) external onlyVault {
        // Skip if no reward adapter configured
        if (address(rewardAdapter) == address(0)) return;

        // Note: Vault has already called setApprovalForAll(rewardAdapter, true) on the
        // NFT manager during addPool(). The reward adapter can then call approve(gauge, tokenId)
        // because it's an approved operator. We don't need to call approve() here - and we
        // can't anyway since StakingManager is not the NFT owner or an approved operator.

        // Forward explicit gas to handle Aerodrome's complex gauge deposit operations
        try rewardAdapter.stake{gas: 1000000}(tokenId) {
            address stakingContract = rewardAdapter.getStakingContract(pool);
            emit PositionStaked(tokenId, stakingContract);
        } catch (bytes memory reason) {
            emit StakeFailed(tokenId, reason);
        }
    }

    /// @notice Attempt to unstake a position from reward adapter (gauge)
    /// @param tokenId Position NFT token ID
    /// @param rewardAdapter The reward adapter
    /// @param pool The pool address
    /// @param recipient Address to receive rewards (vault for fee extraction, or user for direct)
    /// @return rewardsEarned Amount of reward tokens claimed (AERO/CAKE)
    /// @return fees0 Amount of token0 trading fees collected during unstake (PancakeSwap only)
    /// @return fees1 Amount of token1 trading fees collected during unstake (PancakeSwap only)
    function tryUnstake(
        uint256 tokenId,
        IRewardAdapter rewardAdapter,
        address pool,
        address recipient
    ) external onlyVault returns (uint256 rewardsEarned, uint256 fees0, uint256 fees1) {
        // Skip if no reward adapter or not staked
        if (address(rewardAdapter) == address(0)) return (0, 0, 0);
        if (!rewardAdapter.isStaked(tokenId)) return (0, 0, 0);

        // Try to claim rewards first
        // Forward explicit gas to handle Aerodrome's complex gauge operations
        try rewardAdapter.claimRewards{gas: 1000000}(tokenId, recipient) returns (uint256 earned, uint256 f0, uint256 f1) {
            rewardsEarned = earned;
            fees0 = f0;
            fees1 = f1;
            if (earned > 0) {
                emit StakingRewardsClaimed(tokenId, recipient, rewardAdapter.rewardToken(), earned);
            }
        } catch {
            // Claim failed - continue with unstake
        }

        // V16-L-01 fix: Track reward token balance before/after unstake to capture
        // auto-claimed rewards (PancakeSwap MasterChef auto-harvests CAKE during withdraw).
        // If claimRewards failed, these auto-claimed rewards would otherwise bypass the
        // performance fee pipeline.
        address rewardTokenAddr = rewardAdapter.rewardToken();
        uint256 rewardBalanceBefore = IERC20(rewardTokenAddr).balanceOf(recipient);

        // Unstake the position
        // Forward explicit gas to handle Aerodrome's complex gauge withdraw operations
        try rewardAdapter.unstake{gas: 1000000}(tokenId) {
            address stakingContract = rewardAdapter.getStakingContract(pool);
            emit PositionUnstaked(tokenId, stakingContract);
        } catch (bytes memory reason) {
            emit UnstakeFailed(tokenId, reason);
        }

        // V16-L-01 fix: Capture any auto-claimed rewards that arrived at recipient during unstake
        uint256 rewardBalanceAfter = IERC20(rewardTokenAddr).balanceOf(recipient);
        if (rewardBalanceAfter > rewardBalanceBefore) {
            rewardsEarned += rewardBalanceAfter - rewardBalanceBefore;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PUBLIC STAKING FUNCTION (moved from SnuggleVault to reduce bytecode)
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Stake a position in the reward adapter (gauge)
    /// @dev V17-L-01: Restricted to position owner to prevent unwanted re-staking
    /// @param tokenId The position to stake
    function stakePosition(uint256 tokenId) external {
        // Get position data from vault
        (
            ,              // tokenId
            bytes32 poolId,
            address owner,
            ,              // rangeWidthBps
            ,              // currentTickLower
            ,              // currentTickUpper
            ,              // autoSnuggleEnabled
            ,              // autoCompoundEnabled
            ,              // rebalanceDelay
            ,              // outOfRangeSince
            ,              // totalRebalances
            ,              // lastRebalanceTime
            ,              // depositTimestamp
            ,              // cumulativeFees0
            ,              // cumulativeFees1
            ,              // cumulativeRewards
                           // __reserved
        ) = ISnuggleVaultMinimal(vault).positions(tokenId);

        if (owner == address(0)) revert PositionDoesNotExist();
        if (msg.sender != owner) revert NotPositionOwner();

        // Get reward adapter from pool config
        (
            address pool,
            ,              // token0
            ,              // token1
            ,              // fee
            ,              // tickSpacing
            bool active,
            ,              // positionAdapter
            IRewardAdapter rewardAdapter
        ) = ISnuggleVaultMinimal(vault).approvedPools(poolId);

        // V19-I-04: Verify pool is still active before allowing re-staking
        if (!active) revert PoolNotActive();
        if (address(rewardAdapter) == address(0)) revert NoRewardAdapter();

        // Stake via adapter with try-catch for robustness (M-1 fix)
        // Forward explicit gas to handle Aerodrome's complex gauge deposit operations
        try rewardAdapter.stake{gas: 1000000}(tokenId) {
            emit PositionStaked(tokenId, rewardAdapter.getStakingContract(pool));
        } catch (bytes memory reason) {
            emit StakeFailed(tokenId, reason);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // FEE COMPOUNDING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @notice Process collected trading fees - compound matching token, harvest other
    /// @dev Called by vault during snuggle rebalance. Reads position data from vault.
    /// @param tokenId Position token ID
    /// @param token0 First token address
    /// @param token1 Second token address
    /// @param fees0 Amount of token0 fees collected
    /// @param fees1 Amount of token1 fees collected
    /// @param currentTick Current pool tick
    /// @return compound0 Amount of token0 to compound back into liquidity
    /// @return compound1 Amount of token1 to compound back into liquidity
    function processFeesForCompounding(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 fees0,
        uint256 fees1,
        int24 currentTick
    ) external onlyVault returns (uint256 compound0, uint256 compound1) {
        if (fees0 == 0 && fees1 == 0) return (0, 0);

        // Read position data from vault
        (,, address positionOwner,, int24 tickLower, int24 tickUpper,, bool autoCompoundEnabled,,,,,,,,,) =
            ISnuggleVaultMinimal(vault).positions(tokenId);

        if (!autoCompoundEnabled) {
            _harvestAllFees(tokenId, token0, token1, fees0, fees1, positionOwner);
            return (0, 0);
        }

        // Determine position side
        bool isToken0Position = currentTick < tickLower;
        bool isToken1Position = currentTick >= tickUpper;

        if (!isToken0Position && !isToken1Position) {
            _harvestAllFees(tokenId, token0, token1, fees0, fees1, positionOwner);
            return (0, 0);
        }

        if (isToken0Position) {
            // Compound all token0 fees, harvest all token1 fees
            compound0 = fees0;
            // V20-GAS-01: Combined duplicate if-check
            if (fees1 > 0) {
                feeTransferHelper.transferFromVault(token1, positionOwner, fees1);
                emit FeesHarvestedDirect(tokenId, positionOwner, 0, fees1);
            }
        } else {
            // Compound all token1 fees, harvest all token0 fees
            compound1 = fees1;
            // V20-GAS-01: Combined duplicate if-check
            if (fees0 > 0) {
                feeTransferHelper.transferFromVault(token0, positionOwner, fees0);
                emit FeesHarvestedDirect(tokenId, positionOwner, fees0, 0);
            }
        }

        if (compound0 > 0 || compound1 > 0) emit FeesCompounded(tokenId, positionOwner, compound0, compound1);
    }

    /// @notice Distribute performance fees on trading fee earnings (token0/token1 pair)
    /// @dev Reads fee config from vault. Takes performanceFeeBps% of earnings, splits between treasury and referrer.
    /// @param tokenId Position token ID
    /// @param token0 First token address
    /// @param token1 Second token address
    /// @param earned0 Token0 earnings to take performance fee from
    /// @param earned1 Token1 earnings to take performance fee from
    /// @param positionOwner Position owner
    /// @return remaining0 Token0 remaining after performance fee
    /// @return remaining1 Token1 remaining after performance fee
    function distributePerformanceFees(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 earned0,
        uint256 earned1,
        address positionOwner
    ) external onlyVault returns (uint256 remaining0, uint256 remaining1) {
        if (earned0 == 0 && earned1 == 0) return (0, 0);

        // Read config from vault to save calldata in vault bytecode
        ISnuggleVaultMinimal v = ISnuggleVaultMinimal(vault);
        address treasuryAddr = v.treasury();
        if (treasuryAddr == address(0)) revert TreasuryNotSet();

        if (v.feeExempt(positionOwner)) {
            return (earned0, earned1);
        }

        uint256 feeBps = v.performanceFeeBps();
        uint256 fee0 = (earned0 * feeBps) / BPS_DENOMINATOR;
        uint256 fee1 = (earned1 * feeBps) / BPS_DENOMINATOR;

        uint256 treasury0 = fee0;
        uint256 treasury1 = fee1;

        address positionReferrer = v.referrer(positionOwner);
        if (positionReferrer != address(0)) {
            // Custom rate per referrer, fallback to global
            uint256 referralFeeBps = customReferralBps[positionReferrer];
            if (referralFeeBps == 0) referralFeeBps = v.referralFeeBps();
            if (referralFeeBps > 0) {
                uint256 referral0 = (earned0 * referralFeeBps) / BPS_DENOMINATOR;
                uint256 referral1 = (earned1 * referralFeeBps) / BPS_DENOMINATOR;
                // L-01 fix: Defensive check to prevent underflow
                if (referral0 > fee0) referral0 = fee0;
                if (referral1 > fee1) referral1 = fee1;
                treasury0 = fee0 - referral0;
                treasury1 = fee1 - referral1;

                if (referral0 > 0) {
                    _safeTransferReferral(token0, positionReferrer, positionOwner, referral0, treasuryAddr);
                }
                if (referral1 > 0) {
                    _safeTransferReferral(token1, positionReferrer, positionOwner, referral1, treasuryAddr);
                }
            }
        }

        if (treasury0 > 0) {
            feeTransferHelper.transferFromVault(token0, treasuryAddr, treasury0);
        }
        if (treasury1 > 0) {
            feeTransferHelper.transferFromVault(token1, treasuryAddr, treasury1);
        }

        remaining0 = earned0 - fee0;
        remaining1 = earned1 - fee1;

        emit ProtocolFeesDistributed(tokenId, treasury0, treasury1, fee0 - treasury0, fee1 - treasury1);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════════

    /// @dev Harvest all fees to user (no compounding)
    function _harvestAllFees(
        uint256 tokenId,
        address token0,
        address token1,
        uint256 fees0,
        uint256 fees1,
        address positionOwner
    ) internal {
        if (fees0 > 0) {
            feeTransferHelper.transferFromVault(token0, positionOwner, fees0);
        }
        if (fees1 > 0) {
            feeTransferHelper.transferFromVault(token1, positionOwner, fees1);
        }
        emit FeesHarvestedDirect(tokenId, positionOwner, fees0, fees1);
    }

    /// @dev Safe transfer to referrer with fallback to treasury
    /// @dev Also records referral relationship and earnings to ReferralTracker if configured
    function _safeTransferReferral(
        address token,
        address referrerAddr,
        address userAddr,
        uint256 amount,
        address treasuryAddr
    ) internal {
        bool transferSuccess = true;
        try feeTransferHelper.transferFromVault(token, referrerAddr, amount) {}
        catch {
            feeTransferHelper.transferFromVault(token, treasuryAddr, amount);
            transferSuccess = false;
        }

        // Record to tracker (only if transfer to referrer succeeded)
        if (transferSuccess && address(referralTracker) != address(0)) {
            // Record the referral relationship (idempotent - will skip if already recorded)
            try referralTracker.recordReferral(userAddr) {}
            catch {
                // Already recorded or other non-critical error
            }
            // Record the earnings
            try referralTracker.recordEarnings(referrerAddr, token, amount) {}
            catch {
                // Recording failed - not critical, continue
            }
        }
    }
}

